// ResNet-18 W8A8 photo-classification demo on the LiteRT Micro (TFLM) interpreter.
//
// Classifies the real ImageNet-1k photos generated by scripts/gen_demo_data.py
// and prints the top-3 classes for each, next to the ground-truth label. Each
// output is also checked against the LiteRT reference-kernel logits, so the
// demo doubles as an end-to-end check on real (non-random) inputs.
//
// Usage:  resnet18_demo [N]   classify only the first N photos (default: all).
// On RV64 (Spike), mcycle / minstret are reported per inference.

#include <cstdint>
#include <cstring>

#ifdef __riscv
static inline uint64_t rv_rdcycle(void) {
  uint64_t v;
  __asm__ volatile("rdcycle %0" : "=r"(v));
  return v;
}
static inline uint64_t rv_rdinstret(void) {
  uint64_t v;
  __asm__ volatile("rdinstret %0" : "=r"(v));
  return v;
}
#endif  // __riscv

#include "demo_data/demo_images.h"
#include "model/gen_micro_mutable_op_resolver.h"
#include "model/resnet18_int8_channelwise_model_data.h"
#include "tensorflow/lite/micro/micro_interpreter.h"
#include "tensorflow/lite/micro/micro_log.h"
#include "tensorflow/lite/micro/system_setup.h"
#include "tensorflow/lite/schema/schema_generated.h"

#ifndef WORKLOAD_ARENA_SIZE
#define WORKLOAD_ARENA_SIZE (3 * 1024 * 1024)
#endif

namespace {
alignas(16) uint8_t g_tensor_arena[WORKLOAD_ARENA_SIZE];

constexpr int kTopK = 5;
constexpr int kShownK = 3;

int ParseCount(int argc, char** argv) {
  if (argc < 2) return kDemoNumImages;
  int n = 0;
  for (const char* p = argv[1]; *p >= '0' && *p <= '9'; ++p) n = n * 10 + (*p - '0');
  return (n <= 0 || n > kDemoNumImages) ? kDemoNumImages : n;
}

// Indices of the k largest logits, highest first; ties go to the lower index.
void TopK(const int8_t* logits, int n, int* top) {
  for (int k = 0; k < kTopK; ++k) {
    int best = -1;
    for (int i = 0; i < n; ++i) {
      bool taken = false;
      for (int j = 0; j < k; ++j) taken |= (top[j] == i);
      if (!taken && (best < 0 || logits[i] > logits[best])) best = i;
    }
    top[k] = best;
  }
}
}  // namespace

int main(int argc, char** argv) {
  tflite::InitializeTarget();

  const tflite::Model* model =
      tflite::GetModel(g_resnet18_int8_channelwise_model_data);
  if (model->version() != TFLITE_SCHEMA_VERSION) {
    MicroPrintf("Model schema version %d != supported %d",
                static_cast<int>(model->version()), TFLITE_SCHEMA_VERSION);
    return 1;
  }

  tflite::MicroMutableOpResolver<kNumberOperators> resolver = get_resolver();
  tflite::MicroInterpreter interpreter(model, resolver, g_tensor_arena,
                                       sizeof(g_tensor_arena));
  if (interpreter.AllocateTensors() != kTfLiteOk) {
    MicroPrintf("AllocateTensors() failed");
    return 1;
  }

  TfLiteTensor* input = interpreter.input(0);
  TfLiteTensor* output = interpreter.output(0);
  if (input->type != kTfLiteInt8 || output->type != kTfLiteInt8 ||
      input->bytes != kDemoImageBytes || output->bytes != kDemoNumClasses) {
    MicroPrintf("Unexpected I/O tensors: in %d B, out %d B",
                static_cast<int>(input->bytes),
                static_cast<int>(output->bytes));
    return 1;
  }

  const int count = ParseCount(argc, argv);
  MicroPrintf("ResNet-18 W8A8 ImageNet demo: %d photo(s)", count);
  MicroPrintf("");

  int top1_correct = 0;
  int top5_correct = 0;
  int ref_mismatches = 0;
  for (int n = 0; n < count; ++n) {
    const DemoImage& img = g_demo_images[n];
    std::memcpy(input->data.int8, img.pixels, input->bytes);

#ifdef __riscv
    const uint64_t cycle_start = rv_rdcycle();
    const uint64_t instret_start = rv_rdinstret();
#endif
    if (interpreter.Invoke() != kTfLiteOk) {
      MicroPrintf("Invoke() failed");
      return 1;
    }
#ifdef __riscv
    const uint64_t cycles = rv_rdcycle() - cycle_start;
    const uint64_t instret = rv_rdinstret() - instret_start;
#endif

    const int8_t* logits = output->data.int8;
    int top[kTopK];
    TopK(logits, kDemoNumClasses, top);

    int max_abs_diff = 0;
    for (int i = 0; i < kDemoNumClasses; ++i) {
      int diff = logits[i] - img.ref_logits[i];
      if (diff < 0) diff = -diff;
      if (diff > max_abs_diff) max_abs_diff = diff;
    }
    // Same tolerance as the golden test: 1 LSB of requantization rounding.
    const bool ref_ok = max_abs_diff <= 1;

    const bool hit1 = top[0] == img.label;
    bool hit5 = false;
    for (int k = 0; k < kTopK; ++k) hit5 |= (top[k] == img.label);
    top1_correct += hit1;
    top5_correct += hit5;
    ref_mismatches += !ref_ok;

    MicroPrintf("[%2d/%d] %s", n + 1, count, img.file);
    MicroPrintf("        truth: %s", g_imagenet_labels[img.label]);
    for (int k = 0; k < kShownK; ++k) {
      MicroPrintf("        #%d %-24s (logit %4d)%s", k + 1,
                  g_imagenet_labels[top[k]], logits[top[k]],
                  top[k] == img.label ? "  <- correct" : "");
    }
    MicroPrintf("        %s | LiteRT reference %s (max |diff| %d)",
                hit1 ? "top-1 HIT" : (hit5 ? "top-5 hit" : "MISS"),
                ref_ok ? "match" : "MISMATCH", max_abs_diff);
#ifdef __riscv
    MicroPrintf("        cycles %lld, instret %lld", (long long)cycles,
                (long long)instret);
#endif
    MicroPrintf("");
  }

  MicroPrintf("top-1 accuracy: %d / %d", top1_correct, count);
  MicroPrintf("top-5 accuracy: %d / %d", top5_correct, count);
  MicroPrintf("matches LiteRT reference: %d / %d", count - ref_mismatches, count);
  MicroPrintf(ref_mismatches == 0 ? "PASS" : "FAIL");
  return ref_mismatches == 0 ? 0 : 1;
}
